using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ProtectionEffect", menuName = "Data/Battle/Effects/Protection Effect")]
public class ProtectionEffect : Effect
{
	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		int num = effectAmount - 1;
		if (num == 0)
		{
			RemoveEffect(num, effectOwner);
		}
		return num;
	}
}
